const verify=sourceVerify.replaceAll('Q001','Q201').replaceAll('--id=1','--id=201').replace('n<1||n>200','n<201||n>400').replace('String(i+1)','String(i+201)').replace('Q201..Q200','Q201..Q400').replace("track:'sql-200'","track:'sql-more'");
const manifest=defs.map(d=>({id:d.id,tech:'sql',family:d.family,scenario:d.scenario,semanticKey:d.semanticKey,variant:d.variant,title:`${d.family}, scenario ${d.scenario}: ${d.variant}`,prompt:`prompts/${d.id}.txt`,starter:`starters/${d.id}.sql`,solution:`solutions/${d.id}.sql`,test:`tests/${d.id}.cjs`}));
const files=new Map([['runtime.cjs',runtime],['verify.cjs',verify],['manifest.json',JSON.stringify(manifest,null,2)+'\n']]);
for(const d of defs){
 files.set(`solutions/${d.id}.sql`,d.sql+'\n');files.set(`starters/${d.id}.sql`,'-- TODO: write your SQL here');
 files.set(`tests/${d.id}.cjs`,`'use strict';\n// Identical seed/assertions for reference and learner SQL.\nconst grade=require('../runtime.cjs');\nconst spec=${JSON.stringify(d.spec,null,2)};\nmodule.exports=sql=>grade(sql,spec);\n`);
 files.set(`prompts/${d.id}.txt`,`${d.id} — family ${d.family}, scenario ${d.scenario}: ${d.variant}\n\nTask\n${d.task}\n\nDialect\nSQLite ${'3.49.1'} using Node node:sqlite DatabaseSync. JSON/FTS5, generated columns, PRAGMAs, rowid, date functions and EQP syntax/text are SQLite-specific. This is a related scenario within its family, not a claim of a wholly unrelated concept.\n\nFresh seed (foreign_keys=ON)\n${d.spec.seed}\n\nConcrete example\nThe first result row on this seed is ${JSON.stringify(d.expected[0])}.\n\nExpected shape\nColumns: ${Object.keys(d.expected[0]).join(', ')}. Exact ordered rows, including NULL and duplicates:\n${JSON.stringify(d.expected,null,2)}\n\n${d.probes?'Post-result integrity assertions:\n'+JSON.stringify(d.probes,null,2)+'\n\n':''}Submission\nWrite SQL in starters/${d.id}.sql. The final statement returns the graded rows; preceding statements may change only this disposable database. Blank SQL returns [] and fails. No helper SQL implements a blank answer. Reference and starter use the same tests. Use ORDER BY for the stated output order.\n${d.expected[0].detail?'EXPLAIN QUERY PLAN returns native plan rows; the runtime compares detail strings only, ignoring numeric node identifiers/estimates. See GUIDE for version caveat.\n':''}Reference: node sql-more/verify.cjs --id=${d.id}\nLearner: node sql-more/verify.cjs --starters --id=${d.id}\n`);
}
files.set('GUIDE.txt',`SQL-more: Q201..Q400, 200 scenarios in 20 families\n\nNode v22.16.0 and SQLite 3.49.1 verified, including JSON functions and FTS5. No packages, sqlite3 CLI, network, or services. SQL is executed for real in a fresh DatabaseSync(':memory:') with foreign_keys=ON for each exercise.\n\nCommands from unionboot:\n node sql-more/verify.cjs --inventory\n node sql-more/verify.cjs --id=Q201\n node sql-more/verify.cjs --id=201\n node sql-more/verify.cjs --starters --id=Q201\n node sql-more/verify.cjs\n node sql-more/verify.cjs --starters\n\nInventory never opens a database. Exit 0=all selected pass; 1=grading failure including SQL errors; 2=CLI/manifest/inventory parse error. Numeric IDs are 201..400 (not ordinal1..200). Reports: verification-solution.json, verification-starter.json and per-ID suffixes such as verification-solution-Q201.json. Results include phase/errorType/error; all blank TODO starters must fail exact nonempty expected rows.\n\nEach prompt has complete seed, policy, example, exact output aliases and rows. Tests grade the actual final query result; mutation/constraint exercises may also run integrity probes. These deterministic educational tests are not anti-hardcoding security sandboxes or proof for arbitrary inputs. SQL may access local SQLite capabilities; only run trusted learner code.\n\nTokenizer supports simple semicolon-separated queries/DDL/DML, SQL quotes and comments. CREATE TRIGGER BEGIN...END bodies and sqlite shell dot commands are outside scope. Only final statement returns graded rows.\nEQP text targets SQLite 3.49.1; optimizer details can change on another Node/SQLite version. Numeric node IDs/estimates ignored; ordered detail strings graded. FTS5 uses default unicode61 tokenizer, no custom extension. Generated columns/index metadata and JSON operators are SQLite-specific. Native lower/NOCASE are ASCII-oriented. No true boolean storage type; flags are integers/NULL.\nFinancial exercises use integer units/cents and explicit rounding, not accounting advice. Graph paths enumerate tiny finite simple paths, not scalable shortest-path algorithms. Queue/transaction tasks use one connection and verify state, not contention or distributed worker safety. Views are projections, not authorization boundaries. Closure maintenance examples assume the seeded acyclic tree; no automatic cycle enforcement.\n\nFamilies\n${families.map((f,i)=>`${i+1}. ${f} (Q${201+i*10}..Q${210+i*10})`).join('\n')}\n\nAuthoring\n../build-sql-more.cjs preflights all 200 reference definitions against manually specified expected rows before emitting, enforces unique family|semanticKey, and refuses existing sql-more directory. It reads the reviewed SQL200 CLI template at authoring time only; generated sql-more is runtime-independent. Never delete learner work to regenerate. Fix generator-first and surgically replace affected generated files only after comparing old contents.\n\nVerification responsibility\nAuthor preflight checks all references while building. Focused emitted-file smoke checks accompany handoff; coordinator runs complete reference and blank suites as the integrated gate. Do not confuse preflight evidence with those full-suite reports.\n`);
for(const [name,text]of files)if(name.endsWith('.cjs'))new vm.Script(text,{filename:name});
fs.mkdirSync(target);for(const folder of ['prompts','starters','solutions','tests'])fs.mkdirSync(path.join(target,folder));
for(const [name,text]of files)fs.writeFileSync(path.join(target,name),text,{flag:'wx'});
console.log('EMITTED '+defs.length+' exercises, '+files.size+' files, IDs Q201..Q400.');


